// InnovateX 3.0 — Week 1: ESP32 Blink
// Recap: LED + Resistor + Breadboard — now controlled by code!

const int LED_PIN = 2;  // GPIO2, wired through a 220ohm resistor to the LED

void setup() {
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  digitalWrite(LED_PIN, HIGH);  // LED ON
  delay(500);
  digitalWrite(LED_PIN, LOW);   // LED OFF
  delay(500);
}
